// ─────────────────────────────────────────────────────────────────────────────
// Student Tours / University Travel — page copy.
//
// English and Portuguese are fully authored here. The other nine locales
// intentionally receive NO body copy in this batch: t() falls through to the
// English source of truth rather than shipping machine-translated prose. Their
// SEO metadata (title/description/OG) IS natively authored — see
// src/components/seo/route-metadata.ts.
//
// Truth rules applied to every string below: no university partnerships, no
// accreditation, no academic credit, no testimonials, no student statistics,
// no safety absolutes. Group-size wording stays "designed for" / "can be
// considered with advance planning" — never a guarantee of availability.
// ─────────────────────────────────────────────────────────────────────────────

