  // University Groups child page
  ug_breadcrumb: 'University Groups',
  ug_eyebrow: 'FOR GROUP COORDINATORS',
  ug_h1: 'University Group Travel in Morocco',
  ug_sub: 'How group size, lead time and logistics actually shape a Moroccan student programme \u2014 written for the person organising it.',
  ug_intro: 'Morocco Grand Adventure coordinates the Moroccan side of a university or student programme: transport, accommodation, guides, activities and on-the-ground scheduling. This page explains what genuinely changes as a group grows, so a coordinator can plan with realistic expectations instead of guesswork.',
  ug_sizes_h2: 'What changes with group size',
  ug_sizes_intro: 'Every band below is planned differently. Nothing here is a guarantee of availability \u2014 it is how we scope a programme before confirming anything.',
  ug_s1_t: 'Small groups (up to 30)', ug_s1_d: 'The most flexible band. One or two vehicles, a single guide per site, and itineraries that can still change close to departure. Most riads and desert camps absorb this size comfortably.',
  ug_s2_t: '30\u201350 participants', ug_s2_d: 'Usually a coach or a small vehicle convoy. Accommodation starts splitting across properties, so arrival and meal timings need coordinating. Site visits are staggered to keep groups manageable.',
  ug_s3_t: '50\u2013100 participants', ug_s3_d: 'Multiple coaches, several guides, and accommodation blocked across more than one property. Desert nights are split between camps. Meal service and transfers need fixed timings rather than flexible ones.',
  ug_s4_t: '100\u2013150 participants', ug_s4_d: 'Effectively several parallel sub-groups on staggered schedules sharing one route. Requires earlier confirmation because coach fleets and camp capacity in Merzouga are finite during peak months.',
  ug_s5_t: 'Approximately up to 300', ug_s5_d: 'Can be considered with substantial advance planning and coordinated logistics. At this scale transport, accommodation, guides and scheduling are all built as a dedicated operation, and we confirm what is actually available before proposing it. We do not promise capacity we have not secured.',
  ug_factors_h2: 'What group size affects',
  ug_f1_t: 'Transportation', ug_f1_d: 'Vehicle type and count, convoy timings, and how long boarding realistically takes at each stop.',
  ug_f2_t: 'Accommodation', ug_f2_d: 'Whether one property can host the group, or rooms are blocked across several \u2014 and how that changes meal service.',
  ug_f3_t: 'Scheduling', ug_f3_d: 'Larger groups move in staggered waves. Site entry, meals and departures shift from flexible to fixed.',
  ug_f4_t: 'Activities', ug_f4_d: 'Camel treks, 4x4 outings and workshops run in rotations rather than all at once.',
  ug_f5_t: 'Coordination', ug_f5_d: 'More guides and a named on-the-ground contact managing the day rather than a single driver-guide.',
  ug_f6_t: 'Lead time', ug_f6_d: 'The single biggest factor. Earlier planning gives larger groups meaningfully more flexibility, especially in spring and autumn.',
  ug_process_h2: 'How coordination works',
  ug_p1_t: 'Tell us about the group', ug_p1_d: 'Institution, approximate numbers, dates and arrival city.',
  ug_p2_t: 'Define the objectives', ug_p2_d: 'Academic focus, subjects, interests and the level of activity.',
  ug_p3_t: 'Review dates and logistics', ug_p3_d: 'We check what is realistic for that size, season and route.',
  ug_p4_t: 'Build the Moroccan programme', ug_p4_d: 'Route, accommodation, guides and experiences, proposed for review.',
  ug_p5_t: 'Confirm the plan', ug_p5_d: 'Details, timings and logistics adjusted until the plan fits, then confirmed in writing.',
  ug_p6_t: 'Coordinate arrival and travel', ug_p6_d: 'Airport transfers, welcome and the first day organised in advance.',
  ug_p7_t: 'Experience Morocco', ug_p7_d: 'Local coordination throughout, from the medinas to the dunes.',
  ug_coord_h2: 'One coordinator organises for everyone',
  ug_coord_p: 'A professor, faculty member, student leader or university administrator can arrange the Moroccan programme on behalf of the whole group. Students do not each book separately. We work with one named contact, confirm every element with that person before scheduling, and keep a single plan that everyone travels on.',
  ug_faq_h2: 'Group coordination \u2014 FAQ',
  ug_q1: 'Is there a minimum group size?', ug_a1: 'There is no fixed minimum. Student Tours are designed for organised student and university groups — tell us your numbers and we will advise on what works best; very small parties are often a better fit on our standard private tours.',
  ug_q2: 'Can you really handle 300 participants?', ug_a2: 'A group approaching that size can be considered with substantial advance planning and coordinated logistics. It is planned as a dedicated operation, not as a scaled-up small tour, and we confirm actual availability of transport, accommodation and guides before proposing anything. We do not guarantee capacity in advance.',
  ug_q3: 'How far ahead should we start?', ug_a3: 'Earlier planning gives larger groups more flexibility with transportation, accommodation and scheduling. Three to six months ahead is useful for most group programmes, and larger groups travelling in spring or autumn benefit from more.',
  ug_q4: 'Can one person book for everyone?', ug_a4: 'Yes. One coordinator arranges the Moroccan programme for the group, and we confirm every element with that person before it is scheduled.',
  ug_q5: 'Can the programme follow our academic calendar?', ug_a5: 'Yes. Start and end cities, travel days and daily timings are all adjustable around a university schedule.',
  ug_q6: 'Do you provide academic credit?', ug_a6: 'No. We are a Moroccan travel operator, not an academic institution. Credit remains entirely with your university.',
  ug_q7: 'What exactly does Morocco Grand Adventure organise?', ug_a7: 'The Moroccan side: private transport and drivers, accommodation including desert camps, local guides, airport transfers, activities and cultural experiences, itinerary scheduling and on-the-ground coordination.',
  ug_cta_h2: 'Start with your group details',
  ug_cta_p: 'Send us the approximate number of participants, your dates, arrival city and academic focus. We will come back with what is realistic for that size and season.',
  ug_cta: 'Talk to a Group Coordinator',
  ug_back: 'Back to Student Tours',

