  // 02 — More than a trip
  st_02_eyebrow: '01 — THE IDEA',
  st_02_h2: 'More Than a Trip. A Journey Students Remember.',
  st_02_p1: 'A well-designed student journey brings classroom subjects into real places, real people and real situations. A history lesson becomes a walk through an ancient medina. A geography lesson becomes a route from the High Atlas to the dunes of Erg Chebbi.',
