  // 15 — How it works + FAQ
  st_15_h2: 'How It Works',
  st_15_s1_t: 'Tell us about your group', st_15_s1_d: 'Institution, approximate numbers, dates and arrival city.',
  st_15_s2_t: 'Define the goals', st_15_s2_d: 'Academic focus, subjects, interests and the level of activity.',
  st_15_s3_t: 'Build the itinerary', st_15_s3_d: 'We propose a route, accommodation and experiences to review.',
  st_15_s4_t: 'Review & confirm', st_15_s4_d: 'Adjust details, timings and logistics until the plan fits.',
  st_15_s5_t: 'Arrive in Morocco', st_15_s5_d: 'Airport welcome, transport and guides ready on the ground.',
  st_15_s6_t: 'Experience Morocco', st_15_s6_d: 'Local coordination throughout, from the medinas to the dunes.',
  st_15_faq_h2: 'Student Tours in Morocco — FAQ',
  st_15_q1: 'Can you create a custom itinerary for our university group?',
  st_15_a1: 'Yes. Every student programme we run is built from the group’s objectives, dates and interests rather than from a fixed catalogue.',
  st_15_q2: 'Can programmes be adapted around academic objectives?',
  st_15_a2: 'Yes. Tell us the subject focus and we will propose sites, guides and experiences that support it, and adjust pacing so there is time to actually look and discuss.',
  st_15_q3: 'Is there a minimum group size?',
  st_15_a3: 'There is no fixed minimum. Student Tours are designed for organised student and university groups — tell us your numbers and we will advise on what works best; very small parties are often a better fit on our standard private tours.',
  st_15_q4: 'Can one person book for the whole group?',
  st_15_a4: 'Yes. A single coordinator — professor, faculty member, student leader or university administrator — can organise the Moroccan programme on behalf of the group. Students do not need to make separate individual bookings.',
  st_15_q5: 'Can you handle groups of 100, 200 or up to 300 participants?',
  st_15_a5: 'Groups of up to approximately 300 participants can be considered with advance planning and coordinated logistics. A larger group is not handled the same way as a smaller one: transport, accommodation, guides, activities and scheduling all need considerably more lead time, and we confirm availability before anything is promised.',
  st_15_q6: 'Can you organise transportation for student groups?',
  st_15_a6: 'Yes — private vehicles with professional drivers, sized to the group, for the whole route including transfers between cities.',
  st_15_q7: 'Can you arrange desert accommodation?',
  st_15_a7: 'Yes. We are based in Merzouga and can arrange desert camps near Erg Chebbi as well as hotels and riads along the route.',
  st_15_q8: 'Can we include Marrakech, Fes and the Sahara in one programme?',
  st_15_a8: 'Yes. A route linking Marrakech, the Sahara and Fes normally needs around seven days to work comfortably.',
  st_15_q9: 'How far in advance should a university contact you?',
  st_15_a9: 'Earlier planning generally provides more flexibility, especially during popular spring and autumn travel periods. Three to six months in advance can provide useful flexibility for group planning. April can be an excellent period for many student programmes, depending on the itinerary and regions visited.',
  st_15_q10: 'Can you help with airport transfers?',
  st_15_a10: 'Yes, from Marrakech, Casablanca, Fes, Agadir and Errachidia.',
  st_15_q11: 'Can we request a programme around a specific subject?',
  st_15_a11: 'Yes — history, architecture, anthropology, environment, food culture and others. Tell us the subject and we will build the route around it.',
  st_15_q12: 'Can the itinerary be adapted to the university’s schedule?',
  st_15_a12: 'Yes. Start and end cities, travel days and daily timings are all adjustable.',
  st_15_q13: 'Do you provide academic credit?',
  st_15_a13: 'No. We are a Moroccan travel operator, not an academic institution. Credit remains entirely with your university.',
  st_15_alt: 'Student group at the kasbah of Aït Ben Haddou, Morocco',

