  ug_breadcrumb: "Grupos Universitarios",
  ug_eyebrow: "PARA COORDINADORES DE GRUPO",
  ug_h1: "Viajes de Grupos Universitarios en Marruecos",
  ug_sub: "Cómo el tamaño del grupo, el tiempo de antelación y la logística moldean realmente un programa estudiantil en Marruecos — escrito para quien lo organiza.",
  ug_intro: "Morocco Grand Adventure coordina la parte marroquí de un programa universitario o estudiantil: transporte, alojamiento, guías, actividades y la programación sobre el terreno. Esta página explica qué cambia realmente a medida que un grupo crece, para que un coordinador pueda planificar con expectativas realistas en lugar de suposiciones.",
  ug_sizes_h2: "Qué cambia según el tamaño del grupo",
  ug_sizes_intro: "Cada rango a continuación se planifica de forma distinta. Nada aquí es una garantía de disponibilidad — así es como dimensionamos un programa antes de confirmar nada.",
  ug_s1_t: "Grupos pequeños (hasta 30)",
  ug_s1_d: "El rango más flexible. Uno o dos vehículos, un solo guía por sitio, e itinerarios que aún pueden cambiar cerca de la salida. La mayoría de los riads y campamentos del desierto absorben este tamaño sin dificultad.",
  ug_s2_t: "30–50 participantes",
  ug_s2_d: "Normalmente un autocar o un pequeño convoy de vehículos. El alojamiento empieza a dividirse entre varios establecimientos, por lo que hay que coordinar los horarios de llegada y comidas. Las visitas se escalonan para mantener los grupos manejables.",
  ug_s3_t: "50–100 participantes",
  ug_s3_d: "Varios autocares, varios guías, y alojamiento reservado en más de un establecimiento. Las noches en el desierto se dividen entre campamentos. El servicio de comidas y los traslados necesitan horarios fijos en lugar de flexibles.",
  ug_s4_t: "100–150 participantes",
