  ug_s5_t: "Hasta aproximadamente 300",
  ug_s5_d: "Puede considerarse con una planificación anticipada sustancial y una logística coordinada. A esta escala, el transporte, el alojamiento, los guías y la programación se construyen como una operación dedicada, y confirmamos lo que realmente está disponible antes de proponerlo. No prometemos capacidad que no hayamos asegurado.",
  ug_factors_h2: "Qué afecta el tamaño del grupo",
