  ug_p5_d: "Se ajustan detalles, horarios y logística hasta que el plan se ajuste, luego se confirma por escrito.",
  ug_p6_t: "Coordinamos la llegada y el viaje",
  ug_p6_d: "Traslados desde el aeropuerto, bienvenida y el primer día organizados con antelación.",
  ug_p7_t: "Experimenten Marruecos",
  ug_p7_d: "Coordinación local durante todo el viaje, desde las medinas hasta las dunas.",
  ug_coord_h2: "Un coordinador organiza para todos",
  ug_coord_p: "Un profesor, miembro del profesorado, líder estudiantil o administrador universitario puede organizar el programa marroquí en nombre de todo el grupo. Los estudiantes no reservan cada uno por separado. Trabajamos con una persona de contacto designada, confirmamos cada elemento con ella antes de programar, y mantenemos un único plan en el que todos viajan.",
  ug_faq_h2: "Coordinación de grupos — Preguntas frecuentes",
  ug_q1: "¿Hay un tamaño mínimo de grupo?",
  ug_a1: "No hay un mínimo fijo. Los Viajes Estudiantiles están diseñados para grupos organizados de estudiantes y universidades — indíquennos su número y les asesoraremos sobre lo que funciona mejor; los grupos muy pequeños suelen encajar mejor en nuestros tours privados estándar.",
  ug_q2: "¿Realmente pueden gestionar 300 participantes?",
  ug_a2: "Un grupo que se acerque a ese tamaño puede considerarse con una planificación anticipada sustancial y una logística coordinada. Se planifica como una operación dedicada, no como un tour pequeño ampliado, y confirmamos la disponibilidad real de transporte, alojamiento y guías antes de proponer nada. No garantizamos capacidad por adelantado.",
  ug_q3: "¿Con cuánta antelación deberíamos empezar?",
  ug_a3: "Planificar con más antelación da a los grupos grandes más flexibilidad en transporte, alojamiento y programación. De tres a seis meses de antelación suele ser útil para la mayoría de los programas de grupo, y los grupos más grandes que viajan en primavera u otoño se benefician de más tiempo.",
  ug_q4: "¿Puede una sola persona reservar para todos?",
  ug_a4: "Sí. Un coordinador organiza el programa marroquí para el grupo, y confirmamos cada elemento con esa persona antes de programarlo.",
  ug_q5: "¿Puede el programa seguir nuestro calendario académico?",
  ug_a5: "Sí. Las ciudades de inicio y fin, los días de viaje y los horarios diarios son todos ajustables según el calendario universitario.",
  ug_q6: "¿Ofrecen crédito académico?",
  ug_a6: "No. Somos un operador de viajes marroquí, no una institución académica. El crédito permanece enteramente en manos de su universidad.",
  ug_q7: "¿Qué organiza exactamente Morocco Grand Adventure?",
  ug_a7: "La parte marroquí: transporte privado y chóferes, alojamiento incluyendo campamentos en el desierto, guías locales, traslados desde el aeropuerto, actividades y experiencias culturales, programación del itinerario y coordinación sobre el terreno.",
  ug_cta_h2: "Empiecen con los detalles de su grupo",
  ug_cta_p: "Envíennos el número aproximado de participantes, sus fechas, ciudad de llegada y enfoque académico. Les responderemos con lo que es realista para ese tamaño y temporada.",
