  st_02_p1: "Un viaje estudiantil bien diseñado lleva las materias del aula a lugares reales, personas reales y situaciones reales. Una lección de historia se convierte en un paseo por una antigua medina. Una lección de geografía se convierte en una ruta desde el Alto Atlas hasta las dunas de Erg Chebbi.",
  st_02_p2: "La arquitectura se lee en los muros de tierra de una kasbah. La cultura se entiende a través de la comida, la artesanía, el idioma y la vida cotidiana ordinaria. Y el Sahara convierte un itinerario en una experiencia de la que los estudiantes siguen hablando años después.",
