  st_04_places_h3: "Lugares que llevan una lección",
  st_04_places_p: "Fez es sede de Al-Qarawiyyin, uno de los centros de aprendizaje en funcionamiento continuo más antiguos del mundo. Aït Ben Haddou muestra cómo la arquitectura de tierra respondió al clima, la defensa y el comercio. Marrakech se lee como una lección de espacio público, desde la Kutubiyya hasta las plazas y zocos que la rodean. El Alto Atlas conecta el clima, la agricultura, el agua y las comunidades de montaña en una sola tarde. Y el Sahara explica la adaptación humana mejor que cualquier diapositiva.",
