  st_14_f6_d: "Encuentros significativos y respetuosos con anfitriones marroquíes.",
  st_14_honesty: "Morocco Grand Adventure no otorga crédito académico ni reclama acreditación institucional. Organizamos la parte marroquí de su programa — rutas, guías, logística y experiencias — en torno a la intención académica que usted defina.",
