  st_15_s5_d: "Bienvenida en el aeropuerto, transporte y guías listos sobre el terreno.",
  st_15_s6_t: "Experimenten Marruecos",
  st_15_s6_d: "Coordinación local durante todo el viaje, desde las medinas hasta las dunas.",
  st_15_faq_h2: "Viajes Estudiantiles en Marruecos — Preguntas Frecuentes",
  st_15_q1: "¿Pueden crear un itinerario personalizado para nuestro grupo universitario?",
  st_15_a1: "Sí. Cada programa estudiantil que organizamos se construye a partir de los objetivos, fechas e intereses del grupo, en lugar de un catálogo fijo.",
  st_15_q2: "¿Pueden adaptarse los programas según objetivos académicos?",
  st_15_a2: "Sí. Indíquennos el enfoque temático y propondremos sitios, guías y experiencias que lo respalden, ajustando el ritmo para que haya tiempo de observar y debatir de verdad.",
  st_15_q3: "¿Hay un tamaño mínimo de grupo?",
  st_15_a3: "No hay un mínimo fijo. Los Viajes Estudiantiles están diseñados para grupos organizados de estudiantes y universidades — indíquennos su número y les asesoraremos sobre lo que funciona mejor; los grupos muy pequeños suelen encajar mejor en nuestros tours privados estándar.",
  st_15_q4: "¿Puede una sola persona reservar para todo el grupo?",
  st_15_a4: "Sí. Un único coordinador — profesor, miembro del profesorado, líder estudiantil o administrador universitario — puede organizar el programa marroquí en nombre del grupo. Los estudiantes no necesitan hacer reservas individuales por separado.",
  st_15_q5: "¿Pueden gestionar grupos de 100, 200 o hasta 300 participantes?",
  st_15_a5: "Los grupos de hasta aproximadamente 300 participantes pueden considerarse con planificación anticipada y logística coordinada. Un grupo más grande no se gestiona igual que uno más pequeño: el transporte, el alojamiento, los guías, las actividades y la programación necesitan considerablemente más tiempo de antelación, y confirmamos la disponibilidad antes de prometer nada.",
  st_15_q6: "¿Pueden organizar el transporte para grupos de estudiantes?",
  st_15_a6: "Sí — vehículos privados con chóferes profesionales, dimensionados según el grupo, para toda la ruta incluyendo traslados entre ciudades.",
  st_15_q7: "¿Pueden organizar alojamiento en el desierto?",
  st_15_a7: "Sí. Tenemos base en Merzouga y podemos organizar campamentos en el desierto cerca de Erg Chebbi, así como hoteles y riads a lo largo de la ruta.",
  st_15_q8: "¿Podemos incluir Marrakech, Fez y el Sahara en un solo programa?",
  st_15_a8: "Sí. Una ruta que enlaza Marrakech, el Sahara y Fez normalmente necesita alrededor de siete días para funcionar con comodidad.",
  st_15_q9: "¿Con cuánta antelación debería contactarnos una universidad?",
  st_15_a9: "Planificar con más antelación generalmente proporciona más flexibilidad, especialmente durante los periodos populares de viaje de primavera y otoño. De tres a seis meses de antelación puede proporcionar una flexibilidad útil para la planificación de grupos. Abril puede ser un periodo excelente para muchos programas estudiantiles, según el itinerario y las regiones visitadas.",
  st_15_q10: "¿Pueden ayudar con los traslados desde el aeropuerto?",
  st_15_a10: "Sí, desde Marrakech, Casablanca, Fez, Agadir y Errachidia.",
  st_15_q11: "¿Podemos solicitar un programa en torno a una materia específica?",
  st_15_a11: "Sí — historia, arquitectura, antropología, medio ambiente, cultura alimentaria y otras. Indíquennos la materia y construiremos la ruta en torno a ella.",
  st_15_q12: "¿Puede adaptarse el itinerario al calendario de la universidad?",
  st_15_a12: "Sí. Las ciudades de inicio y fin, los días de viaje y los horarios diarios son todos ajustables.",
  st_15_q13: "¿Ofrecen crédito académico?",
  st_15_a13: "No. Somos un operador de viajes marroquí, no una institución académica. El crédito permanece enteramente en manos de su universidad.",
  st_15_alt: "Grupo de estudiantes en la kasbah de Aït Ben Haddou, Marruecos",
