  st_16_body: "Indícanos el tamaño de tu grupo, tus fechas, las materias y objetivos académicos, tu ciudad de llegada y salida, y la duración que tienes en mente. Te responderemos con una ruta, una estructura y un plan claro para la parte marroquí de tu programa.",
