  st_08_h2: 'Um país. Muitas salas de aula.',
  st_08_i1_t: 'CULTURA', st_08_i1_d: 'Tradições vivas, hospitalidade, música e artesanato que os estudantes conhecem pessoalmente, em vez de lerem sobre eles.',
  st_08_i2_t: 'HISTÓRIA', st_08_i2_d: 'Dinastias, cidades imperiais e rotas comerciais que ligaram o Mediterrâneo à África Ocidental.',
  st_08_i3_t: 'GEOGRAFIA', st_08_i3_d: 'Costa atlântica, cordilheiras, vales, oásis e deserto — a poucas horas uns dos outros.',
