  st_09_eyebrow: '05 — PARA COORDENADORES',
  st_09_h2: 'Por trás da experiência, há um plano.',
  st_09_body: 'Uma universidade ou um responsável de grupo não deve ter de coordenar cada detalhe local a partir de outro país. A Morocco Grand Adventure pode reunir toda a componente marroquina do programa, para que o coordenador se concentre nas pessoas, nos objetivos e na própria experiência.',
  st_09_h3: 'Elementos que podemos coordenar',
  st_09_e1: 'Transporte privado e motoristas',
  st_09_e2: 'Guias locais',
  st_09_e3: 'Hotéis, riads e acampamentos no deserto',
  st_09_e4: 'Transfers de aeroporto',
  st_09_e5: 'Atividades de grupo e oficinas',
  st_09_e6: 'Experiências culturais',
  st_09_e7: 'Itinerários à medida e calendarização',
  st_09_e8: 'Coordenação no terreno',
  st_09_note: 'Todos os elementos são confirmados com o responsável do grupo antes de serem agendados.',
  st_09_groups_h3: 'Dimensão do grupo',
  st_09_groups_p: 'As Viagens para Estudantes são concebidas para grupos organizados de estudantes e universitários. Um único coordenador — professor, docente, responsável estudantil ou administrador universitário — pode organizar o programa marroquino em nome de todos, pelo que os estudantes não precisam de reservar individualmente. Grupos até cerca de 300 participantes podem ser considerados com planeamento antecipado e logística coordenada; grupos maiores exigem mais tempo de preparação para transporte, alojamento, guias e calendarização, e a disponibilidade é sempre confirmada antes de qualquer compromisso.',
  st_09_cta: 'Falar sobre o seu grupo',
  st_09_alt: 'Grupo de estudantes com traje amazigh tradicional num oásis de palmeiras, Marrocos',

  st_10_h2: 'Menos logística. Mais experiência.',
  st_10_intro: 'Um processo simples e transparente, do primeiro contacto à chegada — para que o coordenador saiba sempre o que acontece a seguir. Moldamos a componente marroquina do programa à dimensão do grupo, às datas, aos objetivos académicos, aos pontos de chegada e partida, à duração, aos interesses, ao orçamento e aos requisitos da universidade.',

