  st_14_h2: 'Escolha o foco de aprendizagem',
  st_14_intro: 'Diga-nos o que o programa deve ensinar. Moldamos a rota, os guias e as experiências em torno desse foco.',
  st_14_f1_t: 'História e património', st_14_f1_d: 'Cidades imperiais, kasbahs, sítios históricos e rotas comerciais.',
  st_14_f2_t: 'Cultura e sociedade', st_14_f2_d: 'Comunidades, tradições, gastronomia, língua e vida quotidiana.',
  st_14_f3_t: 'Ambiente e geografia', st_14_f3_d: 'Montanhas, vales, oásis, sistemas de água e deserto.',
  st_14_f4_t: 'Arquitetura', st_14_f4_d: 'Medinas, construção em terra, artesanato e património urbano.',
  st_14_f5_t: 'Aventura', st_14_f5_d: 'Caminhadas, rotas de 4x4, dunas e experiências de equipa ao ar livre.',
  st_14_f6_t: 'Intercâmbio cultural', st_14_f6_d: 'Encontros significativos e respeitosos com anfitriões marroquinos.',
  st_14_honesty: 'A Morocco Grand Adventure não atribui créditos académicos nem reivindica acreditação institucional. Organizamos a componente marroquina do seu programa — rotas, guias, logística e experiências — em torno da intenção académica que definir.',

  st_15_h2: 'Como funciona',
  st_15_s1_t: 'Fale-nos do seu grupo', st_15_s1_d: 'Instituição, número aproximado, datas e cidade de chegada.',
  st_15_s2_t: 'Defina os objetivos', st_15_s2_d: 'Foco académico, matérias, interesses e nível de atividade.',
  st_15_s3_t: 'Construa o itinerário', st_15_s3_d: 'Propomos uma rota, alojamento e experiências para análise.',
  st_15_s4_t: 'Reveja e confirme', st_15_s4_d: 'Ajustamos detalhes, horários e logística até o plano encaixar.',
  st_15_s5_t: 'Chegue a Marrocos', st_15_s5_d: 'Receção no aeroporto, transporte e guias prontos no terreno.',
  st_15_s6_t: 'Viva Marrocos', st_15_s6_d: 'Coordenação local do princípio ao fim, das medinas às dunas.',
  st_15_faq_h2: 'Viagens para estudantes em Marrocos — perguntas frequentes',
  st_15_q1: 'Podem criar um itinerário à medida para o nosso grupo universitário?',
  st_15_a1: 'Sim. Todos os programas para estudantes que organizamos partem dos objetivos, das datas e dos interesses do grupo, e não de um catálogo fixo.',
  st_15_q2: 'Os programas podem ser adaptados aos objetivos académicos?',
  st_15_a2: 'Sim. Indique-nos o foco temático e propomos locais, guias e experiências que o apoiem, ajustando o ritmo para haver tempo para observar e debater.',
  st_15_q3: 'Existe uma dimensão mínima de grupo?',
  st_15_a3: 'Não existe uma dimensão mínima fixa. As Viagens para Estudantes são concebidas para grupos organizados de estudantes e universitários — diga-nos o número de participantes e aconselhamo-lo sobre a melhor opção; grupos muito pequenos costumam encaixar melhor nas nossas viagens privadas habituais.',
  st_15_q4: 'Uma só pessoa pode reservar para todo o grupo?',
  st_15_a4: 'Sim. Um único coordenador — professor, docente, responsável estudantil ou administrador universitário — pode organizar o programa marroquino em nome do grupo. Os estudantes não precisam de fazer reservas individuais.',
  st_15_q5: 'Conseguem receber grupos de 100, 200 ou até 300 participantes?',
  st_15_a5: 'Grupos até cerca de 300 participantes podem ser considerados com planeamento antecipado e logística coordenada. Um grupo maior não é tratado da mesma forma que um grupo mais pequeno: transporte, alojamento, guias, atividades e calendarização exigem bastante mais antecedência, e confirmamos a disponibilidade antes de qualquer compromisso.',
  st_15_q6: 'Podem organizar o transporte para grupos de estudantes?',
  st_15_a6: 'Sim — veículos privados com motoristas profissionais, dimensionados ao grupo, para todo o percurso, incluindo transfers entre cidades.',
  st_15_q7: 'Podem tratar do alojamento no deserto?',
  st_15_a7: 'Sim. Estamos sediados em Merzouga e podemos organizar acampamentos no deserto perto de Erg Chebbi, bem como hotéis e riads ao longo da rota.',
  st_15_q8: 'Podemos combinar Marrakech, Fes e o Saara num só programa?',
  st_15_a8: 'Sim. Uma rota que liga Marrakech, o Saara e Fes precisa normalmente de cerca de sete dias para funcionar com conforto.',
  st_15_q9: 'Com quanta antecedência deve uma universidade contactar-vos?',
  st_15_a9: 'Planear mais cedo oferece geralmente mais flexibilidade, sobretudo nos períodos muito procurados da primavera e do outono. Três a seis meses de antecedência podem dar uma flexibilidade útil no planeamento de grupo. Abril pode ser um excelente período para muitos programas de estudantes, consoante o itinerário e as regiões visitadas.',
  st_15_q10: 'Podem ajudar com os transfers de aeroporto?',
  st_15_a10: 'Sim, a partir de Marrakech, Casablanca, Fes, Agadir e Errachidia.',
  st_15_q11: 'Podemos pedir um programa centrado numa matéria específica?',
  st_15_a11: 'Sim — história, arquitetura, antropologia, ambiente, cultura alimentar e outras. Indique-nos a matéria e construímos a rota em torno dela.',
  st_15_q12: 'O itinerário pode adaptar-se ao calendário da universidade?',
  st_15_a12: 'Sim. As cidades de início e fim, os dias de viagem e os horários diários são todos ajustáveis.',
  st_15_q13: 'Atribuem créditos académicos?',
  st_15_a13: 'Não. Somos um operador turístico marroquino, não uma instituição académica. Os créditos dependem inteiramente da sua universidade.',
  st_15_alt: 'Grupo de estudantes na kasbah de Aït Ben Haddou, Marrocos',

