  st_home_body: 'Programmi culturali, educativi e di avventura per università, organizzazioni studentesche e gruppi guidati da docenti — organizzati in tutto il Marocco da un team locale sahariano. Pensati per gruppi di studenti e universitari organizzati.',
  st_home_cta: 'Esplora i Viaggi Studenteschi',

