  st_sd_cta_body: 'Teilen Sie uns mit, von wo Ihre Gruppe anreist, wie viele Studierende kommen und was sie mitnehmen sollen. Wir gestalten die Reise danach, statt Ihnen ein festes Paket zu senden.',
