  st_06_eyebrow: '03 — PROGRAMMA-ERVARINGEN',
  st_06_h2: 'Bouw de Ervaring Rond Uw Studenten',
  st_06_c1_t: 'Culturele onderdompeling',
  st_06_c1_d: 'Lokale tradities, voedsel, ambachtelijke workshops, muziek en het dagelijkse Marokkaanse leven.',
  st_06_c2_t: 'Sahara en woestijn',
  st_06_c2_d: 'Merzouga, Erg Chebbi, kameeltrekking, woestijnkampen en Saharaanse cultuur.',
  st_06_c3_t: 'Educatieve reizen',
  st_06_c3_d: 'Geschiedenis, geografie, architectuur en duurzaamheid, ter plaatse bekeken.',
  st_06_c4_t: 'Avontuur en teamervaringen',
  st_06_c4_d: '4x4-uitstapjes, duinbuggy\'s, wandelen en groepsuitdagingen waar passend.',
  st_06_c5_t: 'Stad en erfgoed',
  st_06_c5_d: 'Marrakech, Fes, Rabat, Meknès, Casablanca en Chefchaouen.',
  st_06_c6_t: 'Aangepaste universitaire programma\'s',
  st_06_c6_d: 'Reisroutes vormgegeven rond academische doelen, duur en groepsgrootte.',
  st_06_alt1: 'Studentengroep met henna en lokale Marokkaanse gastheren buiten een winkel, Marokko',
  st_06_alt2: 'Kameelkaravaan die de duinen van Erg Chebbi oversteekt bij zonsondergang, Marokko',
  st_06_alt3: 'Traditionele leerlooierijen in de medina van Fes, Marokko',
