  st_07_eyebrow: '04 — DE SAHARA',
  st_07_h2: 'Breng het Klaslokaal naar de Sahara.',
  st_07_body: 'Erg Chebbi is niet alleen een landschap om te fotograferen. Het is een omgeving die gesprekken opent die studenten zelden voeren in een collegezaal.',
  st_07_th1: 'Woestijnecologie en klimaat',
  st_07_th2: 'Water, oases en schaarste',
  st_07_th3: 'Nomadisch en Amazigh-erfgoed',
  st_07_th4: 'Trans-Saharaanse handelsroutes',
  st_07_th5: 'Nachthemels en navigatie',
  st_07_th6: 'Menselijke aanpassing en bestaansmiddelen',
  st_07_footer: 'MERZOUGA · ERG CHEBBI · PROVINCIE ERRACHIDIA',
  st_07_alt: 'Kameelkaravaan die de duinen van Erg Chebbi oversteekt bij zonsondergang, Marokko',

  st_08_h2: 'Eén land. Vele klaslokalen.',
  st_08_i1_t: 'CULTUUR', st_08_i1_d: 'Levende tradities, gastvrijheid, muziek en ambacht die studenten persoonlijk ontmoeten in plaats van erover te lezen.',
  st_08_i2_t: 'GESCHIEDENIS', st_08_i2_d: 'Dynastieën, keizerlijke steden en handelsroutes die de Middellandse Zee verbonden met West-Afrika.',
  st_08_i3_t: 'GEOGRAFIE', st_08_i3_d: 'Atlantische kust, bergketens, valleien, oases en woestijn — slechts uren van elkaar verwijderd.',
  st_08_i4_t: 'ARCHITECTUUR', st_08_i4_d: 'Medina\'s, riads en kasbahs, waar aarde, water en geometrie een structurele taal worden.',
  st_08_i5_t: 'GEMEENSCHAP', st_08_i5_d: 'Bergdorpen, oasesteden en woestijnfamilies die nog altijd de landschappen vormgeven waarin ze leven.',
  st_08_i6_t: 'VOEDSEL', st_08_i6_d: 'Markten, specerijen, landbouw en gedeelde maaltijden als directe en eerlijke weg naar een cultuur.',
  st_08_i7_t: 'MILIEU', st_08_i7_d: 'Water, droogte, aanpassing en het fragiele evenwicht dat een oase in leven houdt.',
  st_08_i8_t: 'SAHARA', st_08_i8_d: 'Erg Chebbi: geografie, stilte, nachthemels en een landschap dat studenten niet vergeten.',
  st_08_alt: 'Studentengroep op een quad in de duinen van Merzouga, Marokko',

  st_09_eyebrow: '05 — VOOR COÖRDINATOREN',
  st_09_h2: 'Achter de Ervaring Staat een Plan.',
  st_09_body: 'Een universiteit of groepsleider zou niet elk lokaal detail vanuit een ander land moeten moeten coördineren. Morocco Grand Adventure kan het Marokkaanse deel van het programma samenbrengen, zodat de coördinator zich kan concentreren op mensen, doelen en de ervaring zelf.',
  st_09_h3: 'Elementen die wij kunnen coördineren',
  st_09_e1: 'Privévervoer en chauffeurs',
  st_09_e2: 'Lokale gidsen',
  st_09_e3: 'Hotels, riads en woestijnkampen',
  st_09_e4: 'Luchthaventransfers',
  st_09_e5: 'Groepsactiviteiten en workshops',
  st_09_e6: 'Culturele ervaringen',
  st_09_e7: 'Aangepaste reisroutes en planning',
  st_09_e8: 'Coördinatie ter plaatse',
  st_09_note: 'Elk onderdeel wordt bevestigd met de groepsleider voordat het wordt gepland.',
  st_09_groups_h3: 'Groepsgrootte',
  st_09_groups_p: 'Studentenreizen zijn ontworpen voor georganiseerde studenten- en universitaire groepen. Één coördinator — professor, docent, studentenleider of universiteitsbestuurder — kan het Marokkaanse programma namens iedereen regelen, zodat studenten niet elk afzonderlijk boeken. Groepen tot ongeveer 300 deelnemers kunnen worden overwogen met voorbereidingstijd en gecoördineerde logistiek; grotere groepen hebben meer voorbereidingstijd nodig voor vervoer, accommodatie, gidsen en planning, en beschikbaarheid wordt altijd bevestigd voordat er iets wordt beloofd.',
  st_09_cta: 'Bespreek Uw Groep',
  st_09_alt: 'Studentengroep in traditionele Amazigh-kledij in een palmoase, Marokko',

  st_10_h2: 'Minder Logistiek. Meer Ervaring.',
  st_10_intro: 'Een eenvoudig, transparant proces van het eerste bericht tot de aankomst — zodat een coördinator altijd weet wat er vervolgens komt. Wij vormen het Marokkaanse deel van het programma rond uw groepsgrootte, data, academische doelen, aankomst- en vertrekpunten, duur, interesses, budget en universitaire vereisten.',

  st_11_h2: 'Drie Routes om het Gesprek te Beginnen',
  st_11_intro: 'Voorbeelden, geen vaste pakketten. Elke route kan worden ingekort, verlengd, herschikt of herbouwd rond uw academische doelen.',
  st_11_r1_days: '03', st_11_r1_unit: 'DAGEN',
  st_11_r1_title: 'Marrakech → Sahara',
  st_11_r1_route: 'Marrakech · Aït Ben Haddou · Ouarzazate · Merzouga · Erg Chebbi',
  st_11_r1_themes: 'Geschiedenis / Geografie / Architectuur / Woestijn',
  st_11_r2_days: '04', st_11_r2_unit: 'DAGEN',
  st_11_r2_title: '4-Daagse Marokko Studentenreis',
