  st_13_h2: 'Echte Groepen. Echt Marokko.',
  st_13_line: 'Elke foto op deze pagina is genomen tijdens een Morocco Grand Adventure-reis.',
  st_13_alt1: 'Studentengroep op de duinen van Erg Chebbi bij Merzouga, Marokko',
  st_13_alt2: 'Groep met de Morocco Grand Adventure-vlag in het Atlasgebergte, Marokko',
  st_13_alt3: 'Studentengroep bij de kasbah van Aït Ben Haddou, Marokko',
