  st_14_h2: 'Kies de Leerfocus',
  st_14_intro: 'Vertel ons wat het programma moet onderwijzen. Wij vormen de route, de gidsen en de ervaringen rond die focus.',
  st_14_f1_t: 'Geschiedenis en erfgoed', st_14_f1_d: 'Keizerlijke steden, kasbahs, historische locaties en handelsroutes.',
  st_14_f2_t: 'Cultuur en samenleving', st_14_f2_d: 'Gemeenschappen, tradities, voedsel, taal en dagelijks leven.',
  st_14_f3_t: 'Milieu en geografie', st_14_f3_d: 'Bergen, valleien, oases, watersystemen en woestijn.',
  st_14_f4_t: 'Architectuur', st_14_f4_d: 'Medina\'s, lemen bouw, ambacht en stedelijk erfgoed.',
  st_14_f5_t: 'Avontuur', st_14_f5_d: 'Wandelen, 4x4-routes, duinen en outdoor-teamervaringen.',
  st_14_f6_t: 'Culturele uitwisseling', st_14_f6_d: 'Betekenisvolle, respectvolle ontmoetingen met Marokkaanse gastheren.',
  st_14_honesty: 'Morocco Grand Adventure kent geen academische studiepunten toe en claimt geen institutionele accreditatie. Wij organiseren het Marokkaanse deel van uw programma — routes, gidsen, logistiek en ervaringen — rond de academische intentie die u definieert.',

  st_15_h2: 'Hoe Het Werkt',
  st_15_s1_t: 'Vertel ons over uw groep', st_15_s1_d: 'Instelling, ongeveer aantal deelnemers, data en aankomststad.',
  st_15_s2_t: 'Definieer de doelen', st_15_s2_d: 'Academische focus, vakken, interesses en activiteitsniveau.',
  st_15_s3_t: 'Bouw de reisroute op', st_15_s3_d: 'Wij stellen een route, accommodatie en ervaringen voor ter beoordeling.',
  st_15_s4_t: 'Beoordeel en bevestig', st_15_s4_d: 'Pas details, tijden en logistiek aan totdat het plan past.',
  st_15_s5_t: 'Aankomst in Marokko', st_15_s5_d: 'Welkom op de luchthaven, vervoer en gidsen gereed ter plaatse.',
  st_15_s6_t: 'Beleef Marokko', st_15_s6_d: 'Doorlopende lokale coördinatie, van de medina\'s tot de duinen.',
  st_15_faq_h2: 'Studentenreizen in Marokko — Veelgestelde vragen',
  st_15_q1: 'Kunt u een aangepaste reisroute maken voor onze universitaire groep?',
  st_15_a1: 'Ja. Elk studentenprogramma dat wij uitvoeren, wordt opgebouwd vanuit de doelen, data en interesses van de groep in plaats van vanuit een vaste catalogus.',
  st_15_q2: 'Kunnen programma\'s worden aangepast rond academische doelen?',
  st_15_a2: 'Ja. Laat ons de vakfocus weten en wij stellen locaties, gidsen en ervaringen voor die dit ondersteunen, en passen het tempo aan zodat er tijd is om echt te kijken en te bespreken.',
  st_15_q3: 'Is er een minimale groepsgrootte?',
  st_15_a3: 'Er is geen vast minimum. Studentenreizen zijn ontworpen voor georganiseerde studenten- en universitaire groepen — laat ons uw aantallen weten en we adviseren wat het beste werkt; zeer kleine groepen passen vaak beter bij onze standaard privérondreizen.',
  st_15_q4: 'Kan één persoon boeken voor de hele groep?',
  st_15_a4: 'Ja. Één enkele coördinator — professor, docent, studentenleider of universiteitsbestuurder — kan het Marokkaanse programma namens de groep regelen. Studenten hoeven geen afzonderlijke individuele boekingen te maken.',
  st_15_q5: 'Kunt u groepen van 100, 200 of tot 300 deelnemers aan?',
  st_15_a5: 'Groepen tot ongeveer 300 deelnemers kunnen worden overwogen met voorbereidingstijd en gecoördineerde logistiek. Een grotere groep wordt niet op dezelfde manier behandeld als een kleinere: vervoer, accommodatie, gidsen, activiteiten en planning hebben allemaal aanzienlijk meer voorbereidingstijd nodig, en wij bevestigen beschikbaarheid voordat er iets wordt beloofd.',
  st_15_q6: 'Kunt u vervoer organiseren voor studentengroepen?',
  st_15_a6: 'Ja — privévoertuigen met professionele chauffeurs, op maat van de groep, voor de hele route inclusief transfers tussen steden.',
  st_15_q7: 'Kunt u woestijnaccommodatie regelen?',
  st_15_a7: 'Ja. Wij zijn gevestigd in Merzouga en kunnen woestijnkampen bij Erg Chebbi regelen, evenals hotels en riads langs de route.',
  st_15_q8: 'Kunnen we Marrakech, Fes en de Sahara in één programma opnemen?',
  st_15_a8: 'Ja. Een route die Marrakech, de Sahara en Fes verbindt, heeft normaal gesproken ongeveer zeven dagen nodig om comfortabel te werken.',
  st_15_q9: 'Hoe ver vooraf zou een universiteit contact met u moeten opnemen?',
  st_15_a9: 'Eerdere planning biedt over het algemeen meer flexibiliteit, vooral tijdens de populaire reisperiodes in het voor- en najaar. Drie tot zes maanden vooraf kan nuttige flexibiliteit bieden voor groepsplanning. April kan een uitstekende periode zijn voor veel studentenprogramma\'s, afhankelijk van de reisroute en de bezochte regio\'s.',
  st_15_q10: 'Kunt u helpen met luchthaventransfers?',
  st_15_a10: 'Ja, vanuit Marrakech, Casablanca, Fes, Agadir en Errachidia.',
  st_15_q11: 'Kunnen we een programma aanvragen rond een specifiek vak?',
  st_15_a11: 'Ja — geschiedenis, architectuur, antropologie, milieu, voedselcultuur en andere. Laat ons het vak weten en wij bouwen de route daaromheen.',
  st_15_q12: 'Kan de reisroute worden aangepast aan het rooster van de universiteit?',
  st_15_a12: 'Ja. Start- en eindsteden, reisdagen en dagelijkse tijden zijn allemaal aanpasbaar.',
  st_15_q13: 'Verstrekt u academische studiepunten?',
  st_15_a13: 'Nee. Wij zijn een Marokkaanse reisorganisatie, geen academische instelling. Studiepunten blijven volledig bij uw universiteit.',
  st_15_alt: 'Studentengroep bij de kasbah van Aït Ben Haddou, Marokko',

  st_16_eyebrow: 'PLAN EEN STUDENTENREIS',
  st_16_h2: 'Breng Uw Studenten naar Marokko.',
  st_16_body: 'Laat ons uw groepsgrootte, uw data, de vakken en academische doelen, uw aankomst- en vertrekstad en de beoogde duur weten. Wij reageren met een reisroute, een structuur en een duidelijk plan voor het Marokkaanse deel van uw programma.',
