  st_16_wa: 'WhatsApp',
  st_16_contact: 'Neem Contact op met Morocco Grand Adventure',
  st_16_alt: 'Groep met de Morocco Grand Adventure-vlag in het Atlasgebergte, Marokko',

  st_links_h2: 'Blijf Ontdekken',

  st_home_eyebrow: 'STUDENTEN- EN UNIVERSITEITSREIZEN',
  st_home_h2: 'Marokko is meer dan een bestemming. Het is een ervaring waarvan studenten kunnen leren.',
