  st_08_h2: '一个国家，多间课堂。',
  st_08_i1_t: '文化', st_08_i1_d: '学生亲身接触的鲜活传统、待客之道、音乐与手工艺，而非仅仅是阅读文字。',
  st_08_i2_t: '历史', st_08_i2_d: '连接地中海与西非的王朝、帝王之城与贸易路线。',
  st_08_i3_t: '地理学', st_08_i3_d: '大西洋海岸、山脉、山谷、绿洲与沙漠——彼此之间仅相距数小时车程。',
  st_08_i4_t: '建筑', st_08_i4_d: '麦地那、里亚德和卡斯巴，在那里泥土、水与几何形态构成一种结构语言。',
