  st_09_eyebrow: '05 — 面向协调人',
  st_09_h2: '体验背后，是一份规划。',
  st_09_body: '大学或团队负责人不应该需要从另一个国家协调每一个本地细节。Morocco Grand Adventure可以统筹项目在摩洛哥境内的部分，让协调人能够专注于人员、目标以及体验本身。',
  st_09_h3: '我们可以协调的内容',
  st_09_e1: '私人交通与司机',
  st_09_e2: '当地向导',
  st_09_e3: '酒店、里亚德与沙漠营地',
  st_09_e4: '机场接送',
  st_09_e5: '团队活动与工作坊',
  st_09_e6: '文化体验',
  st_09_e7: '定制行程与日程安排',
  st_09_e8: '现场协调',
  st_09_note: '每个环节都会在安排日程前与团队负责人确认。',
  st_09_groups_h3: '团体规模',
  st_09_groups_p: '学生旅行专为有组织的学生和大学团体设计。一位协调人——教授、教职人员、学生负责人或大学行政人员——可以代表所有人安排摩洛哥部分的项目，这样学生就不需要各自单独预订。最多约300人的团体可在提前规划和统筹后勤的前提下考虑；规模更大的团体需要更长的提前筹备时间来安排交通、住宿、向导和日程，而且在做出任何承诺之前，我们都会先确认实际可用情况。',
  st_09_cta: '咨询你的团体方案',
  st_09_alt: '学生团体穿着传统柏柏尔服饰在棕榈绿洲中',

  st_10_h2: '更少后勤烦恼，更多真实体验。',
  st_10_intro: '从第一条消息到抵达摩洛哥，整个流程简单透明——让协调人始终清楚下一步会发生什么。我们会围绕你们团体的规模、日期、学术目标、抵达与离开地点、行程时长、兴趣方向、预算以及院校要求，来规划项目在摩洛哥境内的部分。',

