  st_15_s6_t: '体验摩洛哥', st_15_s6_d: '从麦地那到沙丘，全程提供当地协调支持。',
  st_15_faq_h2: '摩洛哥学生旅行——常见问题',
  st_15_q1: '你们能为我们的大学团体定制行程吗？',
  st_15_a1: '可以。我们负责的每一个学生项目都是根据团体的目标、日期和兴趣来定制的，而不是套用固定的目录。',
  st_15_q2: '项目能围绕学术目标进行调整吗？',
  st_15_a2: '可以。告诉我们学科重点，我们会提出相应的地点、向导和体验内容，并调整节奏，确保有足够的时间真正观察和讨论。',
  st_15_q3: '有最低团体人数要求吗？',
  st_15_a3: '没有固定的最低人数。学生旅行专为有组织的学生和大学团体设计——告诉我们你们的人数，我们会建议最合适的方案；人数非常少的团体往往更适合我们的标准私人定制行程。',
  st_15_q4: '可以由一个人为整个团体预订吗？',
  st_15_a4: '可以。单一协调人——教授、教职人员、学生负责人或大学行政人员——可以代表团体安排摩洛哥部分的项目。学生不需要分别单独预订。',
  st_15_q5: '你们能接待100人、200人甚至多达300人的团体吗？',
  st_15_a5: '最多约300人的团体可在提前规划和统筹后勤的前提下考虑。规模更大的团体与规模较小的团体处理方式并不相同：交通、住宿、向导、活动和日程安排都需要相当长的提前筹备时间，而且在做出任何承诺之前，我们都会先确认实际可用情况。',
  st_15_q6: '你们能为学生团体安排交通吗？',
  st_15_a6: '可以——配备专业司机、按团体规模配置的私人车辆，覆盖包括城市间接送的整条路线。',
  st_15_q7: '你们能安排沙漠住宿吗？',
  st_15_a7: '可以。我们常驻梅尔祖卡，可以安排厄尔格切比附近的沙漠营地，以及沿途的酒店和里亚德。',
  st_15_q8: '我们可以把马拉喀什、非斯和撒哈拉都安排在一个项目里吗？',
  st_15_a8: '可以。将马拉喀什、撒哈拉和非斯连接起来的行程，通常需要约七天才能安排得从容舒适。',
  st_15_q9: '大学应该提前多久联系你们？',
  st_15_a9: '更早的规划通常能带来更多灵活性，尤其是在春季和秋季这些热门旅行季节。提前三到六个月通常能为团体规划提供有用的灵活空间。根据具体行程和所游览的地区，四月可能是许多学生项目的理想时机。',
  st_15_q10: '你们能协助安排机场接送吗？',
  st_15_a10: '可以，覆盖马拉喀什、卡萨布兰卡、非斯、阿加迪尔和拉希迪亚。',
  st_15_q11: '我们可以请求围绕某个特定学科设计项目吗？',
  st_15_a11: '可以——历史、建筑、人类学、环境、饮食文化等等。告诉我们具体学科，我们会围绕它来设计行程。',
  st_15_q12: '行程能根据大学的日程安排进行调整吗？',
  st_15_a12: '可以。出发和结束城市、出行天数以及每日时间安排，都可以调整。',
