  st_09_eyebrow: '05 — 担当者の方へ',
  st_09_h2: '体験の裏には、計画があります。',
  st_09_body: '大学やグループリーダーが、別の国から現地のあらゆる詳細を調整する必要はないはずです。Morocco Grand Adventureはプログラムのモロッコ側をまとめ上げ、担当者が人々、目標、そして体験そのものに集中できるようにします。',
