  st_09_groups_h3: 'グループの規模',
  st_09_groups_p: '学生旅行は組織化された学生・大学団体向けに設計されています。一人の担当者——教授、教職員、学生リーダー、または大学の管理担当者——が全員の代わりにモロッコ側のプログラムを手配できるため、学生が個別に予約する必要はありません。最大約300名までのグループは、事前計画と調整されたロジスティクスのもとで検討可能です。より大規模なグループは交通、宿泊、ガイド、スケジューリングのためにより長い準備期間が必要であり、何かを約束する前に常に空き状況を確認します。',
