  st_10_h2: '手間は少なく、体験は多く。',
  st_10_intro: '最初のメッセージから到着まで、シンプルで透明なプロセス——担当者が常に次に何が起こるかを把握できるようにします。私たちはグループの規模、日程、学術目標、到着・出発地点、期間、興味、予算、そして大学の要件に合わせてプログラムのモロッコ側を組み立てます。',

